local SettingRefBase = require('Game.Setting.SettingRefBase')
local base = SettingRefBase
local ParseUtils = CS.ParseUtils

---@class LadderTaskVo
local LadderTaskVo = Class("LadderTaskVo", SettingRefBase)

---__int
function LadderTaskVo:__init()
    self.taskAchId = nil              --任务的ID（200000~299999）
    self.desc = nil              --任务说明
    self.taskBelong = nil              --任务所属段位(1-E 2-D 3-C 4-B 5-A 6-S 0-全段位
    self.before = nil              --前置任务
    self.taskContentType = nil              --任务目标类型
    self.taskContentId = nil              --任务目标id
    self.taskContenNum = nil              --任务值num
    self.resetType = nil              --重置类型（0=不重置，一次性任务；1=每日重置；2=赛季重置）
    self.rewardId = nil              --任务奖励
    self.rewardNum = nil              --任务奖励数量
    self.openType = nil              --跳转目标
    self.status = nil              --状态
end

---FillVo
---@param row TableML.TableFileRow
function LadderTaskVo:FillVo(row)
    base.FillVo(self,row)
    self.taskAchId = parse_number(row, "taskAchId")
    self.desc = ParseUtils.ParseLocalizeText(row, "desc")
    -- self.taskBelong = parse_number(row, "taskBelong")    -- 这个字段目前客户端没用，注释掉，这样两个PVP就可以共用这个Vo了
    self.before = parse_string(row, "before", "")
    self.taskContentType = parse_number(row, "taskContentType")
    self.taskContentId = parse_number(row, "taskContentId")
    self.taskContenNum = parse_number(row, "taskContenNum")
    self.resetType = parse_number(row, "resetType", 0)
    self.rewardId = parse_string(row, "rewardId")
    self.rewardNum = parse_string(row, "rewardNum")
    self.openType = parse_string(row, "openType")
    self.status = parse_number(row, "status")

    self.rewards = {}
    local rewardIdList = parse_strings(self.rewardId, ";")
    local rewardNumList = parse_strings(self.rewardNum, ";")
    for i, id in ipairs(rewardIdList) do
        local rewardInfo = {
            goodsId = id,
            goodsNum = rewardNumList[i]
        }
        table.insert(self.rewards, rewardInfo)
    end
end

